import re
from typing import List, Dict, Any, Optional

def _get_child_node(doc, scope, title_suffix):
    scope_node = node_by_title(doc, scope)
    if not scope_node:
        return None
    for child_id in scope_node.get("children", []):
        child = node_by_id(doc, child_id)
        if child and child["title"].endswith(title_suffix):
            return child
    return None

def _parse_object_line(line):
    m = re.match(r"Object (\d+): (.+?) \(", line)
    if m:
        return m.group(1), m.group(2)
    return None, None

def _parse_event_line(line):
    m = re.match(r"Frame (\d+): (.+)", line)
    if not m:
        return None
    frame = int(m.group(1))
    rest = m.group(2)

    if " and " in rest and "collide" in rest:
        parts = rest.split(" and ")
        objs = []
        for p in parts:
            p = p.strip()
            if p.endswith(" collide."): p = p[:-len(" collide.")].strip()
            om = re.match(r"Object (\d+)", p)
            if om: objs.append(om.group(1))
        return {"frame": frame, "type": "collision", "objs": objs}

    if "exits the scene" in rest:
        om = re.match(r"Object (\d+)", rest)
        if om:
            return {"frame": frame, "type": "exit", "obj": om.group(1)}

    if "is in view when the video begins" in rest or "enters the scene" in rest:
        om = re.match(r"Object (\d+)", rest)
        if om:
            return {"frame": frame, "type": "entry", "obj": om.group(1)}

    return None

def _parse_motion_row(rdict):
    try:
        frame = int(rdict['frame'])
        obj_col = rdict['object']
        parts = obj_col.split()
        obj_id = parts[0]
        x = float(rdict['x'])
        y = float(rdict['y'])
        vx = float(rdict['vx'])
        vy = float(rdict['vy'])
        speed = float(rdict['speed'])
        return {"frame": frame, "obj_id": obj_id, "x": x, "y": y, "vx": vx, "vy": vy, "speed": speed, "row_dict": rdict}
    except (ValueError, KeyError):
        return None

def entities(doc, scope) -> list:
    objects_node = _get_child_node(doc, scope, ": Objects")
    if not objects_node or objects_node.get("kind") != "list":
        return []

    ents = []
    for line in objects_node.get("lines", []):
        eid, desc = _parse_object_line(line)
        if eid:
            ents.append({"id": eid, "description": desc})
    return ents

def recorded_end(doc, scope) -> Optional[float]:
    max_frame = -1
    events_node = _get_child_node(doc, scope, ": Events")
    if events_node and events_node.get("kind") == "list":
        for line in events_node.get("lines", []):
            ev = _parse_event_line(line)
            if ev and ev["frame"] > max_frame:
                max_frame = ev["frame"]

    motion_node = _get_child_node(doc, scope, ": Motion log")
    if motion_node and motion_node.get("kind") == "table":
        for ridx, rdict in table_rows(motion_node):
            try:
                f = int(rdict.get('frame', -1))
                if f > max_frame:
                    max_frame = f
            except ValueError:
                pass

    return float(max_frame) if max_frame >= 0 else None

def inputs(doc, scope) -> list:
    events_node = _get_child_node(doc, scope, ": Events")
    motion_node = _get_child_node(doc, scope, ": Motion log")

    entries = {}
    if events_node and events_node.get("kind") == "list":
        lines = events_node.get("lines", [])
        for idx, line in enumerate(lines):
            ev = _parse_event_line(line)
            if ev and ev["type"] == "entry":
                obj = ev["obj"]
                if obj not in entries:
                    entries[obj] = []
                entries[obj].append({"frame": ev["frame"], "line_idx": idx})

    motion_rows = {}
    if motion_node and motion_node.get("kind") == "table":
        for ridx, rdict in table_rows(motion_node):
            mr = _parse_motion_row(rdict)
            if mr:
                obj = mr["obj_id"]
                if obj not in motion_rows:
                    motion_rows[obj] = []
                motion_rows[obj].append({"frame": mr["frame"], "row_idx": ridx, "dict": mr["row_dict"]})

    inputs_list = []
    all_objs = set(list(entries.keys()) + list(motion_rows.keys()))

    for obj in all_objs:
        obj_entries = entries.get(obj, [])
        obj_motion = motion_rows.get(obj, [])
        obj_motion.sort(key=lambda x: x["frame"])

        used_frames = set()

        for entry in obj_entries:
            f = entry["frame"]
            if f in used_frames: continue
            used_frames.add(f)

            state_row = None
            for mr in obj_motion:
                if mr["frame"] == f:
                    state_row = mr
                    break

            src_locs = [[events_node["node_id"], entry["line_idx"]]]
            fields = {}
            if state_row:
                src_locs.append([motion_node["node_id"], state_row["row_idx"], ["frame", "object", "x", "y", "vx", "vy", "speed"]])
                fields["x"] = state_row["dict"]["x"]
                fields["y"] = state_row["dict"]["y"]
                fields["vx"] = state_row["dict"]["vx"]
                fields["vy"] = state_row["dict"]["vy"]
                fields["speed"] = state_row["dict"]["speed"]

            inputs_list.append({
                "id": f"entry_{obj}_{f}",
                "time": float(f),
                "kind": "entry",
                "entities": [obj],
                "fields": fields,
                "src": src_locs
            })

        if not obj_entries and obj_motion:
            mr = obj_motion[0]
            f = mr["frame"]
            fields = {k: mr["dict"][k] for k in ["x", "y", "vx", "vy", "speed"]}
            inputs_list.append({
                "id": f"initial_{obj}_{f}",
                "time": float(f),
                "kind": "initial_state",
                "entities": [obj],
                "fields": fields,
                "src": [[motion_node["node_id"], mr["row_idx"], ["frame", "object", "x", "y", "vx", "vy", "speed"]]]
            })

    return inputs_list

def outcomes(doc, scope) -> list:
    events_node = _get_child_node(doc, scope, ": Events")
    motion_node = _get_child_node(doc, scope, ": Motion log")

    outcomes_list = []

    if events_node and events_node.get("kind") == "list":
        lines = events_node.get("lines", [])
        for idx, line in enumerate(lines):
            ev = _parse_event_line(line)
            if ev and ev["type"] in ["collision", "exit"]:
                f = ev["frame"]
                if ev["type"] == "collision":
                    outcomes_list.append({
                        "time": float(f),
                        "kind": "collision",
                        "entities": ev["objs"],
                        "value": None,
                        "src": [[events_node["node_id"], idx]]
                    })
                elif ev["type"] == "exit":
                    outcomes_list.append({
                        "time": float(f),
                        "kind": "exit",
                        "entities": [ev["obj"]],
                        "value": None,
                        "src": [[events_node["node_id"], idx]]
                    })

    if motion_node and motion_node.get("kind") == "table":
        motion_rows = {}
        for ridx, rdict in table_rows(motion_node):
            mr = _parse_motion_row(rdict)
            if mr:
                obj = mr["obj_id"]
                if obj not in motion_rows:
                    motion_rows[obj] = []
                motion_rows[obj].append({"row_idx": ridx, "dict": mr["row_dict"]})

        for obj, rows in motion_rows.items():
            rows.sort(key=lambda x: int(x["dict"]["frame"]))
            for mr in rows[1:]:
                f = int(mr["dict"]["frame"])
                outcomes_list.append({
                    "time": float(f),
                    "kind": "state_update",
                    "entities": [obj],
                    "value": None,
                    "src": [[motion_node["node_id"], mr["row_idx"], ["frame", "object", "x", "y", "vx", "vy", "speed"]]]
                })

    return outcomes_list


