        for ridx, rdict in table_rows(motion_node):
            try:
                f = int(rdict.get('frame', -1))
                if f > max_frame:
                    max_frame = f
            except ValueError:
                pass

    return float(max_frame) if max_frame >= 0 else None

def inputs(doc, scope) -> list:
    events_node = _get_child_node(doc, scope, ": Events")
    motion_node = _get_child_node(doc, scope, ": Motion log")

    entries = {}
    if events_node and events_node.get("kind") == "list":
        lines = events_node.get("lines", [])
        for idx, line in enumerate(lines):
            ev = _parse_event_line(line)
            if ev and ev["type"] == "entry":
                obj = ev["obj"]
                if obj not in entries:
                    entries[obj] = []
                entries[obj].append({"frame": ev["frame"], "line_idx": idx})

    motion_rows = {}
    if motion_node and motion_node.get("kind") == "table":
        for ridx, rdict in table_rows(motion_node):
            mr = _parse_motion_row(rdict)
            if mr:
                obj = mr["obj_id"]
                if obj not in motion_rows:
                    motion_rows[obj] = []
                motion_rows[obj].append({"frame": mr["frame"], "row_idx": ridx, "dict": mr["row_dict"]})

    inputs_list = []
    all_objs = set(list(entries.keys()) + list(motion_rows.keys()))

    for obj in all_objs:
        obj_entries = entries.get(obj, [])
        obj_motion = motion_rows.get(obj, [])
        obj_motion.sort(key=lambda x: x["frame"])

        used_frames = set()

        for entry in obj_entries:
            f = entry["frame"]
            if f in used_frames: continue
            used_frames.add(f)

            state_row = None
            for mr in obj_motion:
                if mr["frame"] == f:
                    state_row = mr
                    break

            src_locs = [[events_node["node_id"], entry["line_idx"]]]
            fields = {}
            if state_row:
                src_locs.append([motion_node["node_id"], state_row["row_idx"], ["frame", "object", "x", "y", "vx", "vy", "speed"]])
                fields["x"] = state_row["dict"]["x"]
                fields["y"] = state_row["dict"]["y"]
                fields["vx"] = state_row["dict"]["vx"]
                fields["vy"] = state_row["dict"]["vy"]
                fields["speed"] = state_row["dict"]["speed"]

            inputs_list.append({
                "id": f"entry_{obj}_{f}",
                "time": float(f),
                "kind": "entry",
                "entities": [obj],
                "fields": fields,
                "src": src_locs
            })

        if not obj_entries and obj_motion:
            mr = obj_motion[0]
            f = mr["frame"]
            fields = {k: mr["dict"][k] for k in ["x", "y", "vx", "vy", "speed"]}
            inputs_list.append({
                "id": f"initial_{obj}_{f}",
                "time": float(f),
                "kind": "initial_state",
                "entities": [obj],
                "fields": fields,
                "src": [[motion_node["node_id"], mr["row_idx"], ["frame", "object", "x", "y", "vx", "vy", "speed"]]]
            })

    return inputs_list

def outcomes(doc, scope) -> list:
    events_node = _get_child_node(doc, scope, ": Events")
    motion_node = _get_child_node(doc, scope, ": Motion log")

    outcomes_list = []

    if events_node and events_node.get("kind") == "list":
        lines = events_node.get("lines", [])
        for idx, line in enumerate(lines):
            ev = _parse_event_line(line)
            if ev and ev["type"] in ["collision", "exit"]:
                f = ev["frame"]
                if ev["type"] == "collision":
                    outcomes_list.append({
                        "time": float(f),
                        "kind": "collision",
                        "entities": ev["objs"],
                        "value": None,
                        "src": [[events_node["node_id"], idx]]
                    })
                elif ev["type"] == "exit":
                    outcomes_list.append({
                        "time": float(f),
                        "kind": "exit",
                        "entities": [ev["obj"]],
                        "value": None,
                        "src": [[events_node["node_id"], idx]]
                    })

    if motion_node and motion_node.get("kind") == "table":
        motion_rows = {}
        for ridx, rdict in table_rows(motion_node):
            mr = _parse_motion_row(rdict)
            if mr:
                obj = mr["obj_id"]
                if obj not in motion_rows:
                    motion_rows[obj] = []
                motion_rows[obj].append({"row_idx": ridx, "dict": mr["row_dict"]})

        for obj, rows in motion_rows.items():
            rows.sort(key=lambda x: int(x["dict"]["frame"]))
            for mr in rows[1:]:
                f = int(mr["dict"]["frame"])
                outcomes_list.append({
                    "time": float(f),
                    "kind": "state_update",
                    "entities": [obj],
                    "value": None,
                    "src": [[motion_node["node_id"], mr["row_idx"], ["frame", "object", "x", "y", "vx", "vy", "speed"]]]
                })

    return outcomes_list


# ---- step 2: forward model ----
import math
from collections import defaultdict

def simulate(doc, scope, inputs, params, start=None, horizon=None):
    if horizon is None: horizon = 128.0
    if start is None: start = 0.0

    # Gather object histories from inputs
    obj_hist = defaultdict(list)
    all_objs = set()
    for inp in inputs:
        t = inp["time"]
        f = inp.get("fields", {})
        x = float(f.get("x", 0))
        y = float(f.get("y", 0))
        vx = float(f.get("vx", 0))
        vy = float(f.get("vy", 0))
        spd = float(f.get("speed", 0))
        for obj in inp["entities"]:
            obj_hist[obj].append((t, x, y, vx, vy, spd))
            all_objs.add(obj)

    for obj in obj_hist:
        obj_hist[obj].sort(key=lambda r: r[0])

    # Initialise state at `start` from latest record at or before `start`
    cur = {}
    for obj in all_objs:
        rec = obj_hist[obj]
        latest = rec[0]
        for r in rec:
            if r[0] <= start:
                latest = r
        cur[obj] = list(latest)  # [t, x, y, vx, vy, spd]

    outcomes = []
    FPS = 25.6          # ~128 frames / 5 sec
    COLL_DIST = 0.18    # estimated collision threshold
    EXIT_B = 2.8        # estimated scene boundary
    FRICTION = 0.985    # speed decay per frame

    input_times = [inp["time"] for inp in inputs]

    def step_state(st, dt):
        t, x, y, vx, vy, spd = st
        decay = FRICTION ** dt
        vx *= decay
        vy *= decay
        spd = math.hypot(vx, vy)
        x += vx * dt / FPS
        y += vy * dt / FPS
        return [t + dt, x, y, vx, vy, spd]

    t = start
    step = 1.0
    while t <= horizon:
        # Advance all objects
        for obj in cur:
            cur[obj] = step_state(cur[obj], step)

        # Detect collisions
        objs = list(cur.keys())
        for i in range(len(objs)):
            for j in range(i + 1, len(objs)):
                o1, o2 = objs[i], objs[j]
                d = math.hypot(cur[o1][1] - cur[o2][1], cur[o1][2] - cur[o2][2])
                if d < COLL_DIST:
                    outcomes.append({
                        "time": t,
                        "kind": "collision",
                        "entities": [o1, o2],
                        "value": None,
                        "src": []
                    })
                    # Post-collision: reduce speeds to model energy loss / rebound
                    cur[o1][3] *= 0.75
                    cur[o1][4] *= 0.75
                    cur[o1][5] *= 0.75
                    cur[o2][3] *= 0.75
                    cur[o2][4] *= 0.75
                    cur[o2][5] *= 0.75

        # Detect exits
        for obj in list(cur.keys()):
            if abs(cur[obj][1]) > EXIT_B or abs(cur[obj][2]) > EXIT_B:
                outcomes.append({
                    "time": t,
                    "kind": "exit",
                    "entities": [obj],
                    "value": None,
                    "src": []
                })

        # Emit state_update outcomes at recorded sampling points or regular intervals
        is_sample_frame = any(abs(t - it) < 0.5 for it in input_times) or int(t) % 8 == 0
        if is_sample_frame:
            for obj in cur:
                outcomes.append({
                    "time": t,
                    "kind": "state_update",
                    "entities": [obj],
                    "value": None,
                    "src": []
                })

        t += step

    # Keep only outcomes strictly after `start`
    res = [o for o in outcomes if o["time"] > start]

    # Deduplicate collisions (prevent multiple triggers in same frame)
    seen_coll = set()
    final_outcomes = []
    for o in res:
        if o["kind"] == "collision":
            key = tuple(sorted(o["entities"]))
            if key in seen_coll:
                continue
            seen_coll.add(key)
        final_outcomes.append(o)

    return final_outcomes
